<template><div class="page"><div class="head"><h2>巡检任务</h2><p>扫码识别设备后，按关联表单完成巡检，填写内容会自动保存在本机。</p></div><div class="filters"><el-select v-model="query.status" clearable placeholder="全部状态" @change="load"><el-option v-for="(v,k) in statusMap" :key="k" :label="v" :value="k"/></el-select><el-input v-model="query.keyword" clearable placeholder="任务号、设备名称或编号" @keyup.enter="load"/><el-button type="primary" @click="load">查询</el-button></div><div class="cards"><div v-for="x in rows" :key="x.id" class="task-card"><div class="card-top"><b>{{x.targetName}}</b><el-tag :type="tagType(x.status)">{{statusMap[x.status]||x.status}}</el-tag></div><div class="meta">{{x.inspectionTypeName}} · {{x.planName}}</div><div class="meta">计划：{{fmt(x.scheduledAt)}}　截止：{{fmt(x.dueAt)}}</div><div class="meta">责任：{{ownerText(x)}}<el-tag v-if="x.assigneeStatus==='NO_ASSIGNEE'" size="small" type="warning" style="margin-left:6px">岗位空缺</el-tag><el-tag v-else-if="x.assigneeStatus==='UNCLAIMED'&&!x.claimedBy" size="small" style="margin-left:6px">待认领</el-tag><span v-if="x.claimedByName">　已认领：{{x.claimedByName}}</span></div><div class="meta">负责人：{{x.assigneeName||'未指定'}}　{{x.sourceType==='PLAN'?'设备':'对象'}}：{{x.targetCode||'-'}}</div><div class="actions"><el-button plain @click="showQr(x)">任务二维码</el-button><el-button v-if="canClaim(x)" type="warning" plain @click="claim(x)">认领任务</el-button><el-button v-if="canManage&&!finished(x)" plain @click="openReassign(x)">重新归属</el-button><el-button type="primary" plain @click="open(x)">{{['COMPLETED','CLOSED'].includes(x.status)?'查看结果':(x.sourceType==='PLAN'?'开始巡检':'处理任务')}}</el-button></div></div><el-empty v-if="!rows.length" description="暂无巡检任务"/></div>
<el-drawer v-model="visible" :title="current?.targetName||'巡检任务'" size="min(720px,100%)" destroy-on-close><div v-if="current" class="form"><div class="equipment-title">{{current.sourceType==='PLAN'?'本次巡检设备资料':'任务信息'}}</div><el-descriptions v-if="current.sourceType==='PLAN'" :column="1" border><el-descriptions-item label="任务编号">{{current.taskNo}}</el-descriptions-item><el-descriptions-item label="设备编号">{{snapshot.equipmentCode||current.targetCode||'-'}}</el-descriptions-item><el-descriptions-item label="设备名称">{{snapshot.equipmentName||current.targetName||'-'}}</el-descriptions-item><el-descriptions-item label="设备分类">{{snapshot.categoryName||'-'}}</el-descriptions-item><el-descriptions-item label="所属系统">{{snapshot.systemName||'-'}}</el-descriptions-item><el-descriptions-item label="安装位置">{{snapshot.installationLocation||current.locationText||'-'}}</el-descriptions-item><el-descriptions-item label="楼层/区域">{{[snapshot.floorCode,snapshot.areaName].filter(Boolean).join(' / ')||'-'}}</el-descriptions-item><el-descriptions-item label="品牌/型号">{{[snapshot.brand,snapshot.model].filter(Boolean).join(' / ')||'-'}}</el-descriptions-item><el-descriptions-item label="规格/出厂编号">{{[snapshot.specification,snapshot.serialNumber].filter(Boolean).join(' / ')||'-'}}</el-descriptions-item><el-descriptions-item label="责任人">{{snapshot.responsiblePerson||'-'}} {{snapshot.responsiblePhone||''}}</el-descriptions-item><el-descriptions-item label="截止时间">{{fmt(current.dueAt)}}</el-descriptions-item></el-descriptions><h3>{{current.templateName}}</h3><el-alert v-if="current.formMode==='NONE'" title="本任务仅需确认完成，无需填写检查项" type="info" :closable="false" style="margin-bottom:8px"/><template v-if="current.formMode!=='NONE'"><div v-for="f in fields" :key="f.key" class="form-item"><div class="label">{{f.label}}<span v-if="f.required"> *</span><small v-if="f.unit">（{{f.unit}}）</small></div><el-radio-group v-if="f.controlType==='RADIO'" v-model="answers[f.key]" @change="saveLocal"><el-radio-button label="正常"/><el-radio-button label="异常"/></el-radio-group><el-input-number v-else-if="f.controlType==='NUMBER'" v-model="answers[f.key]" @change="saveLocal"/><el-select v-else-if="f.controlType==='SELECT'" v-model="answers[f.key]" @change="saveLocal"><el-option v-for="o in f.options||[]" :key="o" :label="o" :value="o"/></el-select><el-upload v-else-if="f.controlType==='PHOTO'" :action="uploadUrl(f.key)" :headers="uploadHeaders" accept="image/jpeg,image/png" list-type="picture-card" :on-success="uploadSuccess"><span>拍照/上传</span></el-upload><el-input v-else v-model="answers[f.key]" type="textarea" @input="saveLocal"/><div v-if="answers[f.key]==='异常'" class="issue-box"><el-input v-model="issueNotes[f.key]" placeholder="请填写异常情况及整改要求" @input="saveLocal"/></div></div></template><div class="form-item"><div class="label">现场照片{{current.requirePhoto?'（必须上传至少1张）':''}}</div><el-upload :action="uploadUrl()" :headers="uploadHeaders" accept="image/jpeg,image/png" list-type="picture-card" :on-success="uploadSuccess"><span>拍照/上传</span></el-upload><div class="photo-list"><template v-for="a in attachments" :key="a.id"><el-image v-if="isPhotoName(a.fileName)" class="photo-thumb" :src="attachmentUrls[a.id]" :preview-src-list="photoPreviewUrls" :initial-index="photoPreviewUrls.indexOf(attachmentUrls[a.id])" preview-teleported fit="cover"/><a v-else :href="`/api/v1/inspections/tasks/${current.id}/attachments/${a.id}`" target="_blank">{{a.fileName}}</a></template></div></div><el-input v-model="summary" type="textarea" :placeholder="current.sourceType==='PLAN'?'本次巡检说明':'任务完成说明（选填）'" @input="saveLocal"/><div class="draft">{{draftTip}}</div><div v-if="current.logs&&current.logs.length" class="log-block"><div class="log-title">操作记录</div><div v-for="l in current.logs" :key="l.id" class="log-row"><span class="log-time">{{fmt(l.createdAt)}}</span><el-tag size="small" effect="plain">{{logText(l.action)}}</el-tag><span class="log-actor">{{l.actorName||'-'}}</span><span class="log-detail">{{l.detail||''}}</span></div></div><div v-if="current.sourceType==='PLAN'" class="qr-gate"><el-button :type="qrVerified?'success':'warning'" plain @click="openScan">{{qrVerified?'已验证设备 ✓':'扫描设备二维码解锁'}}</el-button><span v-if="!qrVerified" class="qr-tip2">提交前须扫描当前设备二维码</span></div><el-button v-if="!['COMPLETED','CLOSED'].includes(current.status)" type="primary" size="large" class="submit" @click="submit">{{current.sourceType==='PLAN'?'提交巡检结果':'确认完成任务'}}</el-button></div></el-drawer><el-dialog v-model="qrVisible" :title="isCalendarTask(qrTask)?'任务回执二维码':'巡检任务二维码'" width="360"><img v-if="qrTask" class="qr" :src="`/api/v1/inspections/public-qr/${qrTask.accessToken}`"/><p class="qr-tip">{{isCalendarTask(qrTask)?'扫码即可免登录填写回执，链接 7 天内有效':'扫码后登录即可进入该次巡检任务'}}</p></el-dialog><el-dialog v-model="reassignVisible" title="重新归属任务" width="460"><el-form label-width="90"><el-form-item label="任务">{{reassignTarget?.targetName}}</el-form-item><el-form-item label="归属类型"><el-select v-model="reassignForm.ownerType"><el-option label="个人" value="USER"/><el-option label="岗位" value="ROLE"/><el-option label="部门" value="DEPT"/></el-select></el-form-item><el-form-item label="责任对象"><el-select v-if="reassignForm.ownerType==='USER'" v-model="reassignForm.ownerId" filterable placeholder="选择执行人"><el-option v-for="u in ownerOptions.users" :key="u.id" :label="u.name" :value="u.id"/></el-select><el-select v-else-if="reassignForm.ownerType==='ROLE'" v-model="reassignForm.ownerId" filterable placeholder="选择岗位"><el-option v-for="r in ownerOptions.roles" :key="r.id" :label="r.name" :value="r.id"/></el-select><el-tree-select v-else v-model="reassignForm.ownerId" :data="deptTree" :props="{label:'label',children:'children'}" node-key="value" check-strictly :render-after-expand="false" placeholder="选择部门"/></el-form-item></el-form><template #footer><el-button @click="reassignVisible=false">取消</el-button><el-button type="primary" @click="submitReassign">确认重新归属</el-button></template></el-dialog><el-dialog v-model="scanVisible" title="扫描现场设备二维码" width="360px" @close="stopScan"><video ref="videoRef" class="scan-video" playsinline muted></video><canvas ref="canvasRef" style="display:none"></canvas><p class="scan-tip">将摄像头对准设备二维码，识别成功后自动校验并解锁提交</p></el-dialog></div></template>
<script setup lang="ts">import{ref,reactive,computed,onMounted,onBeforeUnmount,nextTick}from'vue';import{useRoute}from'vue-router';import jsQR from'jsqr';import{ElMessage}from'element-plus';import{inspectionApi}from'@/api/inspection';import{useUserStore}from'@/stores/user';import{formatDateTime}from'@/utils/format';const route=useRoute(),store=useUserStore(),token=localStorage.getItem('token')||'',uploadHeaders={Authorization:`Bearer ${token}`};const canManage=computed(()=>store.hasPermission('inspection.plan.manage')),ownerOptions=ref<any>({departments:[],roles:[],users:[]}),reassignVisible=ref(false),reassignTarget=ref<any>(),reassignForm=reactive<any>({ownerType:'DEPT',ownerId:null});const deptTree=computed(()=>{const nodes=(ownerOptions.value.departments||[]).map((d:any)=>({value:d.id,label:d.name,parentId:d.parentId,children:[] as any[]}));const map=new Map(nodes.map((n:any)=>[n.value,n]));const roots:any[]=[];nodes.forEach((n:any)=>{if(n.parentId&&map.has(n.parentId))(map.get(n.parentId) as any).children.push(n);else roots.push(n)});return roots});const finished=(x:any)=>['COMPLETED','CLOSED','CANCELLED'].includes(x.status);function ownerText(x:any){const t=x.ownerType||'USER';if(t==='ROLE')return `岗位：${x.ownerName||'-'}`;if(t==='DEPT')return `部门：${x.ownerName||'-'}`;return `个人：${x.ownerName||x.assigneeName||'-'}`}function canClaim(x:any){return x.planClaimMode==='CLAIM'&&['DEPT','ROLE'].includes(x.ownerType)&&!x.claimedBy&&!finished(x)}async function claim(x:any){await inspectionApi.claim(x.id);ElMessage.success('认领成功');load()}function openReassign(x:any){reassignTarget.value=x;reassignForm.ownerType='DEPT';reassignForm.ownerId=null;reassignVisible.value=true}async function submitReassign(){if(!reassignForm.ownerId)return ElMessage.warning('请选择责任对象');await inspectionApi.reassign(reassignTarget.value.id,{...reassignForm});ElMessage.success('已重新归属');reassignVisible.value=false;load()}const statusMap:any={PENDING:'待巡检',IN_PROGRESS:'巡检中',COMPLETED:'已完成',PENDING_RECTIFICATION:'待整改',RECTIFIED:'待复核',CLOSED:'已闭环',OVERDUE:'已逾期',CANCELLED:'已取消'};const query=reactive({status:'',keyword:''}),rows=ref<any[]>([]),visible=ref(false),current=ref<any>(),fields=ref<any[]>([]),answers=reactive<any>({}),issueNotes=reactive<any>({}),summary=ref(''),draftTip=ref(''),attachments=ref<any[]>([]),attachmentUrls=ref<Record<number,string>>({}),photoPreviewUrls=computed(()=>attachments.value.filter((a:any)=>isPhotoName(a.fileName)&&attachmentUrls.value[a.id]).map((a:any)=>attachmentUrls.value[a.id])),qrVisible=ref(false),qrTask=ref<any>();const unwrap=(r:any)=>r?.data?.data??r?.data??r;const parse=(s:any,d:any)=>{try{return typeof s==='string'?JSON.parse(s):s||d}catch{return d}};const snapshot=computed(()=>parse(current.value?.equipmentSnapshotJson,{}));const fmt=(x:any)=>formatDateTime(x);const tagType=(s:string)=>s==='OVERDUE'?'danger':s==='PENDING_RECTIFICATION'?'warning':['COMPLETED','CLOSED'].includes(s)?'success':'info';const logText=(a:string)=>({CLAIM:'认领',REASSIGN:'改派',SUBMIT:'提交回执',H5_SUBMIT:'H5 提交回执'} as any)[a]||a;const uploadUrl=(photoType='TASK')=>`/api/v1/inspections/tasks/${current.value?.id}/attachments?photoType=${photoType}`;const isPhotoName=(n:any)=>/\.(jpe?g|png|gif|webp|bmp)$/i.test(String(n||''));async function loadAttachmentThumbs(id:any){for(const a of attachments.value){if(!isPhotoName(a.fileName)||attachmentUrls.value[a.id])continue;try{const blob:any=await inspectionApi.attachmentFile(id,a.id);attachmentUrls.value[a.id]=URL.createObjectURL(blob)}catch{}}}async function load(){rows.value=unwrap(await inspectionApi.tasks(query))}async function open(row:any){current.value=row.accessToken&&!row.id?unwrap(await inspectionApi.taskByToken(row.accessToken)):unwrap(await inspectionApi.task(row.id));fields.value=parse(current.value.fieldsJson,[]);attachments.value=unwrap(await inspectionApi.attachments(current.value.id));loadAttachmentThumbs(current.value.id);Object.keys(answers).forEach(k=>delete answers[k]);Object.keys(issueNotes).forEach(k=>delete issueNotes[k]);Object.assign(answers,parse(current.value.resultJson,{}));const draft=localStorage.getItem(`inspection-draft-${current.value.id}`);if(draft&&!current.value.submittedAt){const d=parse(draft,{});Object.assign(answers,d.answers||{});Object.assign(issueNotes,d.issueNotes||{});summary.value=d.summary||'';draftTip.value='已恢复本机自动保存内容'}visible.value=true;qrVerified.value=false;forceCapture()}const isCalendarTask=(x:any)=>!!x&&['CALENDAR','MANUAL'].includes(String(x.sourceType));function showQr(x:any){qrTask.value=x;qrVisible.value=true}async function uploadSuccess(r:any){if(r?.code!==0)return ElMessage.error(r?.message||'上传失败');ElMessage.success('照片上传成功');attachments.value=unwrap(await inspectionApi.attachments(current.value.id));forceCapture()}function saveLocal(){if(!current.value)return;localStorage.setItem(`inspection-draft-${current.value.id}`,JSON.stringify({answers:{...answers},issueNotes:{...issueNotes},summary:summary.value,savedAt:new Date()}));draftTip.value='已自动保存 '+new Date().toLocaleTimeString()}async function submit(){if(current.value.sourceType==='PLAN'&&!qrVerified.value){ElMessage.warning('请先扫描现场设备二维码解锁后再提交');openScan();return}if(current.value.requirePhoto===1&&!attachments.value.length)return ElMessage.warning('该任务要求至少上传1张现场照片');const list=current.value.formMode==='NONE'?[]:fields.value;for(const f of list)if(f.required&&f.controlType!=='PHOTO'&&(answers[f.key]===undefined||answers[f.key]===''))return ElMessage.warning(`请填写：${f.label}`);const issues=list.filter(f=>answers[f.key]==='异常').map(f=>({fieldKey:f.key,fieldLabel:f.label,level:f.issueLevel||'WARNING',description:issueNotes[f.key]||`${f.label}异常`,rectificationRequirement:issueNotes[f.key]||'请及时核查并整改'}));await inspectionApi.submit(current.value.id,{result:{...answers},summary:summary.value,issues});localStorage.removeItem(`inspection-draft-${current.value.id}`);ElMessage.success(issues.length?'已提交，异常已进入整改':(current.value.sourceType==='PLAN'?'巡检已完成':'任务已完成'));visible.value=false;load()}const scanVisible=ref(false),qrVerified=ref(false),scanStream=ref<any>(null),scanRaf=ref<number|null>(null),videoRef=ref<HTMLVideoElement|null>(null),canvasRef=ref<HTMLCanvasElement|null>(null);function forceCapture(){nextTick(()=>{document.querySelectorAll('.form input[type=file]').forEach((el:any)=>el.setAttribute('capture','environment'))})}async function openScan(){if(!current.value)return;scanVisible.value=true;await nextTick();const v=videoRef.value;if(!v)return;try{const stream=await navigator.mediaDevices.getUserMedia({video:{facingMode:'environment'}});scanStream.value=stream;v.srcObject=stream;await v.play();scanRaf.value=requestAnimationFrame(tickScan)}catch(e){ElMessage.error('无法访问摄像头，请确认已授权相机权限')}}function tickScan(){const v=videoRef.value,c=canvasRef.value;if(!v||!c||!scanStream.value)return;if(v.readyState===v.HAVE_ENOUGH_DATA){c.width=v.videoWidth;c.height=v.videoHeight;const ctx=c.getContext('2d',{willReadFrequently:true});if(ctx){ctx.drawImage(v,0,0,c.width,c.height);try{const code=jsQR(ctx.getImageData(0,0,c.width,c.height).data,c.width,c.height);if(code&&code.data){onScanDecoded(code.data);return}}catch(e){}}}scanRaf.value=requestAnimationFrame(tickScan)}function onScanDecoded(text:string){const expected=String(current.value?.equipmentQrToken||'');if(expected&&(text.endsWith('/'+expected)||text===expected)){qrVerified.value=true;ElMessage.success('设备验证通过，可以提交');stopScan();scanVisible.value=false}else{ElMessage.warning('二维码与当前任务设备不匹配，请扫描'+(current.value?.targetName||'当前设备')+'的设备码')}}function stopScan(){if(scanRaf.value){cancelAnimationFrame(scanRaf.value);scanRaf.value=null}if(scanStream.value){scanStream.value.getTracks().forEach((t:any)=>t.stop());scanStream.value=null}if(videoRef.value)videoRef.value.srcObject=null}onMounted(async()=>{await load();ownerOptions.value=unwrap(await inspectionApi.ownerOptions());const taskToken=String(route.query.taskToken||'');if(taskToken)await open({accessToken:taskToken});const taskId=Number(route.query.taskId||0);if(taskId)await open({id:taskId})});onBeforeUnmount(stopScan)
</script>
<style scoped>.page{padding:20px}.head h2{margin:0}.head p,.meta,.draft{color:#777}.filters{display:flex;gap:10px;background:#fff;padding:14px;border-radius:8px;margin:14px 0}.filters .el-input{max-width:360px}.cards{display:grid;grid-template-columns:repeat(auto-fill,minmax(320px,1fr));gap:12px}.task-card{background:#fff;border-radius:9px;padding:16px;border:1px solid #e8ebef}.card-top{display:flex;justify-content:space-between;gap:8px}.meta{font-size:13px;margin-top:9px}.actions{margin-top:14px;text-align:right}.equipment-title{font-weight:700;margin-bottom:10px}.form-item{padding:15px 0;border-bottom:1px solid #eee}.label{font-weight:600;margin-bottom:9px}.label span{color:#f56c6c}.issue-box{margin-top:8px}.submit{width:100%;margin-top:18px}.draft{font-size:12px;margin-top:8px}.photo-list{display:flex;flex-direction:row;flex-wrap:wrap;gap:8px;margin-top:8px}.photo-thumb{width:88px;height:88px;border-radius:6px;cursor:zoom-in}@media(max-width:768px){.photo-thumb{width:30vw;height:30vw;max-width:120px;max-height:120px}}.qr{display:block;width:280px;height:280px;margin:auto}.qr-tip{text-align:center;color:#777}@media(max-width:768px){.page{padding:10px}.filters{display:grid}.filters .el-input{max-width:none}.cards{grid-template-columns:1fr}}.log-block{margin:12px 0;padding:10px 12px;border:1px solid #ebeef5;border-radius:6px;background:#fafbfc}.log-title{font-size:13px;font-weight:600;color:#303133;margin-bottom:6px}.log-row{display:flex;align-items:center;gap:8px;padding:4px 0;font-size:12px;color:#606266;border-top:1px dashed #ebeef5}.log-row:first-of-type{border-top:0}.log-time{flex:none;color:#909399;font-variant-numeric:tabular-nums}.log-actor{flex:none;color:#303133}.log-detail{flex:1;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}.scan-video{width:100%;border-radius:8px;background:#000;display:block}.scan-tip,.qr-tip2{color:#909399;font-size:12px;margin-top:8px;text-align:center}.qr-gate{display:flex;align-items:center;gap:10px;margin:12px 0}
</style>
